// Byte-exact CLI equivalence harness.
// Runs N binaries over a matrix of (argv0, argv, envp) and compares
// stdout / stderr / wait-status byte-for-byte.
#include <cstdio>
#include <cstring>
#include <cstdlib>
#include <string>
#include <vector>
#include <unistd.h>
#include <sys/wait.h>
#include <fcntl.h>
#include <errno.h>

using std::string;
using std::vector;

struct Result {
    int  status = -1;   // raw waitpid status
    int  exitcode = -1; // -1 if signalled
    int  sig = 0;
    string out, err;
    bool spawn_ok = true;
};

struct Case {
    string name;
    string argv0;        // empty -> use binary path
    vector<string> args; // args after argv[0]
    int envmode = 0;     // 0 = inherit, 1 = empty, 2 = explicit list
    vector<string> env;
};

static string drain(int fd) {
    string s;
    char buf[65536];
    ssize_t n;
    while ((n = read(fd, buf, sizeof buf)) > 0) s.append(buf, (size_t)n);
    return s;
}

extern char **environ;

static Result run_case(const string &bin, const Case &c) {
    Result r;
    int op[2], ep[2];
    if (pipe(op) || pipe(ep)) { r.spawn_ok = false; return r; }
    pid_t pid = fork();
    if (pid < 0) { r.spawn_ok = false; return r; }
    if (pid == 0) {
        dup2(op[1], 1); dup2(ep[1], 2);
        close(op[0]); close(op[1]); close(ep[0]); close(ep[1]);
        int devnull = open("/dev/null", O_RDONLY);
        if (devnull >= 0) { dup2(devnull, 0); close(devnull); }

        vector<char *> av;
        string a0 = c.argv0.empty() ? bin : c.argv0;
        av.push_back(const_cast<char *>(a0.c_str()));
        for (auto &a : c.args) av.push_back(const_cast<char *>(a.c_str()));
        av.push_back(nullptr);

        vector<char *> ev;
        char **envp;
        if (c.envmode == 0) {
            envp = environ;
        } else {
            for (auto &e : c.env) ev.push_back(const_cast<char *>(e.c_str()));
            ev.push_back(nullptr);
            envp = ev.data();
        }
        execve(bin.c_str(), av.data(), envp);
        // exec failed
        fprintf(stderr, "EXECFAIL %d %s\n", errno, strerror(errno));
        _exit(127);
    }
    close(op[1]); close(ep[1]);
    r.out = drain(op[0]);
    r.err = drain(ep[0]);
    close(op[0]); close(ep[0]);
    int st = 0;
    waitpid(pid, &st, 0);
    r.status = st;
    if (WIFEXITED(st)) r.exitcode = WEXITSTATUS(st);
    if (WIFSIGNALED(st)) { r.exitcode = -1; r.sig = WTERMSIG(st); }
    return r;
}

static void hexdump(const char *label, const string &s) {
    printf("      %s (%zu bytes):\n", label, s.size());
    for (size_t i = 0; i < s.size(); i += 16) {
        printf("        %04zx  ", i);
        for (size_t j = 0; j < 16; j++) {
            if (i + j < s.size()) printf("%02x ", (unsigned char)s[i + j]);
            else printf("   ");
        }
        printf(" |");
        for (size_t j = 0; j < 16 && i + j < s.size(); j++) {
            unsigned char ch = (unsigned char)s[i + j];
            putchar((ch >= 32 && ch < 127) ? ch : '.');
        }
        printf("|\n");
    }
    if (s.empty()) printf("        <empty>\n");
}

static string esc(const string &s) {
    string o;
    for (unsigned char ch : s) {
        if (ch == '\\') o += "\\\\";
        else if (ch >= 32 && ch < 127) o += (char)ch;
        else { char b[8]; snprintf(b, sizeof b, "\\x%02x", ch); o += b; }
    }
    return o;
}

static string argv_repr(const Case &c) {
    string o = "argv0=[" + esc(c.argv0) + "]";
    o += " args=";
    if (c.args.empty()) o += "<none>";
    size_t lim = c.args.size() > 12 ? 12 : c.args.size();
    for (size_t i = 0; i < lim; i++) o += "[" + esc(c.args[i]) + "]";
    if (c.args.size() > lim) { char b[64]; snprintf(b, sizeof b, "...(%zu total)", c.args.size()); o += b; }
    if (c.envmode == 1) o += " env=<empty>";
    else if (c.envmode == 2) { o += " env={"; for (auto &e : c.env) o += esc(e) + ";"; o += "}"; }
    return o;
}

int main(int argc, char **argv) {
    if (argc < 3) { fprintf(stderr, "usage: runner REF BIN...\n"); return 2; }
    vector<string> bins;
    for (int i = 1; i < argc; i++) bins.push_back(argv[i]);

    // ---- build the matrix -------------------------------------------------
    vector<Case> cases;
    auto add = [&](const string &name, vector<string> args, string a0 = "",
                   int em = 0, vector<string> env = {}) {
        Case c; c.name = name; c.args = std::move(args); c.argv0 = std::move(a0);
        c.envmode = em; c.env = std::move(env); cases.push_back(c);
    };

    // 1. no arguments
    add("no-args", {});

    // 2. five documented example arg sets, 3 passing styles each
    struct Ex { const char *p, *t, *w, *pc; };
