        {"0",   "100", "30", "0.0"},
        {"50",  "100", "50", "0.5"},
        {"100", "100", "80", "1.0"},
        {"25",  "200", "40", "0.125"},
        {"75",  "150", "60", "0.5"},
    };
    for (int i = 0; i < 5; i++) {
        char nm[64];
        snprintf(nm, sizeof nm, "example%d-positional", i + 1);
        add(nm, {ex[i].p, ex[i].t, ex[i].w, ex[i].pc});
        snprintf(nm, sizeof nm, "example%d-key=value", i + 1);
        add(nm, {string("--progress=") + ex[i].p, string("--total=") + ex[i].t,
                 string("--width=") + ex[i].w, string("--percentage=") + ex[i].pc});
        snprintf(nm, sizeof nm, "example%d-key_space_value", i + 1);
        add(nm, {"--progress", ex[i].p, "--total", ex[i].t,
                 "--width", ex[i].w, "--percentage", ex[i].pc});
    }

    // 3. single-argument variants (documented flags + odd values)
    const char *singles[] = {"--help", "-h", "-help", "help", "--version", "-V",
